const {chromium}=require('/opt/tsr/node_modules/playwright');
const timer=setTimeout(()=>{process.stderr.write('authored capability deadline\n');process.exit(124)},30000);timer.unref();
(async()=>{let browser;try{
browser=await chromium.launch({headless:true,chromiumSandbox:true,timeout:15000});
const page=await browser.newPage();await page.setContent('<button id="probe">Ready</button>');
const text=await page.locator('#probe').innerText();
process.stdout.write(JSON.stringify({kind:'authored_runtime_capability',uid:process.getuid(),node:process.version,playwright:require('/opt/tsr/node_modules/playwright/package.json').version,browser:browser.version(),text})+'\n');
await browser.close();clearTimeout(timer);
}catch(e){process.stderr.write(String(e.stack||e)+'\n');if(browser)await browser.close();process.exitCode=2;clearTimeout(timer);}})();
